</template>

<script setup>
import { ref, reactive, computed, watch } from 'vue'
import { createResource, Button, toast } from 'frappe-ui'
import { statusPillClass } from '../data/deviasiStatus'
import { openPdf } from '../composables/pdfViewer'
import { useBackNavigation } from '../composables/useBackNavigation'

const props = defineProps({
	name: { type: String, required: true },
})

const { goBack } = useBackNavigation({ name: 'Deviasi' }, 'Deviasi')

// ===== Ambil detail =====
const detail = createResource({
	url: 'juragan.api.portal.deviasi.get_deviasi_detail',
	method: 'GET',
	auto: false,
	makeParams: () => ({ name: props.name }),
})

const errorMessage = computed(() => {
	if (!detail.error) return ''
	const e = detail.error
	return e?.messages?.[0] || e?.message || 'Gagal memuat detail data.'
})

// ===== Workflow: aksi transisi (approve/reject/cancel) di action bar bawah =====
// Didefinisikan SEBELUM watch(immediate) di bawah, karena watch memanggil
// loadTransitions() saat setup — transRes harus sudah terinisialisasi.
const transitions = ref([])
const transRes = createResource({
	url: 'juragan.api.portal.deviasi.get_deviasi_transitions',
	method: 'GET',
	auto: false,
	makeParams: () => ({ name: props.name }),
	onSuccess: (data) => {
		transitions.value = data || []
	},
	onError: () => {
		transitions.value = []
	},
})
function loadTransitions() {
	transRes.fetch()
}

const actionsOpen = ref(false)
const applying = ref('')
const applyRes = createResource({
	url: 'juragan.api.portal.deviasi.apply_deviasi_transition',
	method: 'POST',
})
async function applyAction(action) {
	if (applying.value) return
	applying.value = action
	try {
		await applyRes.submit({ name: props.name, action })
		await detail.fetch() // status & field ter-update
		loadTransitions() // transisi berikutnya sesuai state baru
		toast.success(`Aksi "${action}" berhasil`)
	} catch (e) {
		toast.error(e?.messages?.[0] || e?.message || `Gagal menerapkan aksi "${action}"`)
	} finally {
		applying.value = ''
		actionsOpen.value = false
	}
}

// Aksi "destruktif" (Reject/Cancel/Tolak/Batal) → tombol merah; selain itu primary.
function isDestructive(action) {
	return /reject|cancel|tolak|batal/i.test(action || '')
}

// ===== Download PDF (hanya saat status "Approved", persis deviasi.js desk) =====
// Desk: refresh() → if (frm.doc.status === "Approved") add_custom_button("Download PDF").
const DEVIASI_PRINT_FORMAT = 'Form Deviasi'
const showPdf = computed(() => (detail.data?.status || '').trim() === 'Approved')

// Endpoint sama dengan desk (frappe.utils.print_format.download_pdf), TAPI
// dirender lewat PdfViewer in-app, bukan window.open: endpoint ini mengirim
// Content-Disposition "attachment" & WebView Android tak punya renderer PDF →
// window.open cuma menghasilkan halaman kosong. PdfViewer (PDF.js) mengambil
// byte-nya with credentials, menampilkannya, dan menyediakan tombol download.
function openDeviasiPdf() {
	const url =
		`/api/method/frappe.utils.print_format.download_pdf` +
		`?doctype=${encodeURIComponent('Deviasi')}` +
		`&name=${encodeURIComponent(props.name)}` +
		`&format=${encodeURIComponent(DEVIASI_PRINT_FORMAT)}` +
		`&no_letterhead=0`
	openPdf(url, `Deviasi ${props.name}`)
}

// Muat detail + transisi tiap kali dokumen berganti (juga saat pertama kali).
watch(
	() => props.name,
	() => {
		detail.fetch()
		loadTransitions()
	},
	{ immediate: true }
)

// ===== Collapse per section =====
// Set berisi index section yang sedang DISEMBUNYIKAN. Default: semua terbuka.
const collapsedSections = ref(new Set())
function isCollapsed(i) {
	return collapsedSections.value.has(i)
}
function toggleSection(i) {
	const next = new Set(collapsedSections.value)
	next.has(i) ? next.delete(i) : next.add(i)
	collapsedSections.value = next
}
watch(
	() => props.name,
	() => {
		collapsedSections.value = new Set()
	}
)

// ===== Cek Rincian Hutang Nasabah (live n8n, dipersist ke dokumen — ala desk) =====
// Klik → layar freeze "Mengambil rincian hutang…" → fetch & simpan ke dokumen →
// muat ulang detail (field rincian terisi) → toast sukses/gagal.
const checking = ref(false)
const rincianRes = createResource({
	url: 'juragan.api.portal.deviasi.cek_rincian_hutang',
	method: 'POST',
})
// Snackbar sendiri (bukan toast frappe-ui): timer auto-dismiss bawaan reka-ui
// ikut fokus window & di webview (Capacitor/Android) sering dianggap tak fokus,
// jadi toast tak pernah hilang sendiri. Snackbar ini punya animasi keluar via
// <Transition> dan hilang sendiri lewat setTimeout.
const snack = reactive({ show: false, type: 'success', message: '' })
let snackTimer = null
function autoToast(type, message) {
	if (snackTimer) clearTimeout(snackTimer)
	snack.type = type
	snack.message = message
	snack.show = true
	snackTimer = setTimeout(() => {
		snack.show = false // memicu animasi keluar
	}, 3500)
}
async function cekRincian() {
	if (checking.value) return
	checking.value = true
	try {
		await rincianRes.submit({ name: props.name })
		await detail.fetch() // muat ulang → field rincian di section ikut ter-update
		autoToast('success', 'Rincian hutang berhasil diambil')
	} catch (e) {
		autoToast('error', e?.messages?.[0] || e?.message || 'Gagal mengambil rincian hutang')
	} finally {
		checking.value = false
	}
}

// ===== Helpers =====
const ID_MONTHS = [
	'Jan',
	'Feb',
	'Mar',
	'Apr',
	'Mei',
	'Jun',
	'Jul',
	'Agu',
	'Sep',
	'Okt',
	'Nov',
	'Des',
]
function formatDate(d) {
	if (!d) return '-'
	const [y, m, day] = String(d).split(' ')[0].split('-')
	if (!y || !m || !day) return d
	return `${day} ${ID_MONTHS[Number(m) - 1] || m} ${y}`
}
// Datetime → "dd Mmm yyyy HH:mm:ss" (jam/menit/detik penting untuk waktu cek).
function formatDateTime(d) {
	if (!d) return '-'
	const [datePart, timePart] = String(d).split(' ')
	const dateStr = formatDate(datePart)
	if (!timePart) return dateStr
	const [hh, mm, ss] = timePart.split('.')[0].split(':')
	if (hh == null) return dateStr
	return `${dateStr} ${hh}:${mm ?? '00'}:${ss ?? '00'}`
}
const rupiah = new Intl.NumberFormat('id-ID', {
	style: 'currency',
	currency: 'IDR',
	minimumFractionDigits: 0,
	maximumFractionDigits: 0,
})
function formatValue(f) {
	const v = f.value
	if (v === null || v === undefined || v === '') return '-'
	if (f.fieldtype === 'Currency') {
		const n = Number(v)
		return Number.isFinite(n) ? rupiah.format(n) : v
	}
	if (f.fieldtype === 'Datetime') return formatDateTime(v)
	if (f.fieldtype === 'Date') return formatDate(v)
	return v
}
function initials(name) {
	if (!name) return '?'
	return name.trim()[0]?.toUpperCase() || '?'
}

</script>
